# Correct the color-1 components as separate pieces; connect lower-1 to 4, then 8, then upper-1.
objs2={
'3':{'shift':(4,6),'cells':[(1,c) for c in range(2,6)]+[(2,2),(2,5),(3,2),(3,5),(4,2),(5,2),(6,2),(6,3)],'marks':[(2,1),(4,5),(5,1),(6,4)]},
'8':{'shift':(12,1),'cells':[(3,18),(3,19),(4,19),(5,16),(5,19),(6,16),(6,19)]+[(7,c) for c in range(16,20)],'marks':[(3,17),(4,16),(5,15),(7,15)]},
'4':{'shift':(0,0),'cells':[(r,c) for r in range(9,14) for c in range(11,15)],'marks':[(8,11),(9,15),(10,10),(14,14)]},
'7':{'shift':(-7,-3),'cells':[(r,4) for r in range(12,18)],'marks':[(12,5),(17,5)]},
'1lower':{'shift':(-7,-7),'cells':[(16,23),(16,24)]+[(r,24) for r in range(17,22)]+[(22,c) for c in range(21,25)],'marks':[(16,22),(21,21),(22,25),(23,24)]},
'1upper':{'shift':(7,-8),'cells':[(10,22),(10,23),(11,22),(12,22),(12,23)],'marks':[(10,24),(12,24)]},
'6':{'shift':(-13,-9),'cells':[(18,12)]+[(19,c) for c in range(12,16)]+[(20,12),(21,12)]+[(22,c) for c in range(12,16)]+[(23,12)],'marks':[(18,11),(19,16),(22,16),(23,11)]}
}
grid2=[[0]*26 for _ in range(26)]; collision2=[]
for name,o in objs2.items():
 dr,dc=o['shift']; val=int(name[0])
 for typ,pts in [('cells',o['cells']),('marks',o['marks'])]:
  for r,c in pts:
   rr,cc=r+dr,c+dc
   if not(0<=rr<26 and 0<=cc<26): collision2.append(('out',name,typ,rr,cc));continue
   v=val if typ=='cells' else 2
   if grid2[rr][cc] and grid2[rr][cc]!=v: collision2.append((rr,cc,grid2[rr][cc],v,name,typ))
   grid2[rr][cc]=v
print('collisions',collision2)
print('\n'.join(' '.join(map(str,row)) for row in grid2))
